public class SearcherCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Searcher impl) {
        try {
            return SearcherChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectSearcher()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectSearcher()));
        check("rejects the returns-0-when-absent bug", false, verdict(new ZeroWhenAbsentSearcher()));
        check("rejects the finds-the-last-occurrence bug", false, verdict(new LastOccurrenceSearcher()));
        check("rejects the crash-on-empty-array bug", false, verdict(new CrashOnEmptySearcher()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectSearcher implements Searcher {
    public int indexOf(int[] values, int target) {
        for (int i = 0; i < values.length; i++) {
            if (values[i] == target) return i;
        }
        return -1;
    }
}

class AlsoCorrectSearcher implements Searcher {
    public int indexOf(int[] values, int target) {
        int i = 0;
        while (i < values.length) {
            if (values[i] == target) return i;
            i++;
        }
        return -1;
    }
}

class ZeroWhenAbsentSearcher implements Searcher {
    public int indexOf(int[] values, int target) {
        for (int i = 0; i < values.length; i++) {
            if (values[i] == target) return i;
        }
        return 0;
    }
}

class LastOccurrenceSearcher implements Searcher {
    public int indexOf(int[] values, int target) {
        int found = -1;
        for (int i = 0; i < values.length; i++) {
            if (values[i] == target) found = i;
        }
        return found;
    }
}

class CrashOnEmptySearcher implements Searcher {
    public int indexOf(int[] values, int target) {
        int i = 0;
        do {
            if (values[i] == target) return i;
            i++;
        } while (i < values.length);
        return -1;
    }
}

