/**
 * TASK: Write the checks that decide whether a Searcher is correct.
 *
 * The Searcher contract:
 *   indexOf(values, target) returns the index of the FIRST value equal to
 *   target, or -1 when target does not appear at all.
 *   An empty array always returns -1.
 *   Examples: indexOf({4, 7, 9}, 7) -> 1, indexOf({4, 7, 9}, 5) -> -1,
 *             indexOf({5, 3, 5}, 5) -> 0, indexOf({}, 1) -> -1
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. One broken implementation THROWS
 * on an empty array, so a crash counts as a failure: wrap your calls in
 * try/catch and return false if anything is thrown.
 *
 * A single "find the value that is there" call passes all three broken
 * implementations. Ask instead: what if the target is missing? What if it
 * appears twice? What if the array is empty?
 */
interface Searcher {
    /* Provided -- do not edit. */
    int indexOf(int[] values, int target);
}

public class SearcherChecker {

    public static boolean isCorrect(Searcher impl) {
        int[] trio = {4, 7, 9};
        int[] duplicates = {5, 3, 5};
        try {
            if (impl.indexOf(trio, 4) != 0) return false;
            if (impl.indexOf(trio, 7) != 1) return false;
            if (impl.indexOf(trio, 9) != 2) return false;
            if (impl.indexOf(trio, 5) != -1) return false;
            if (impl.indexOf(duplicates, 5) != 0) return false;
            if (impl.indexOf(new int[] {}, 1) != -1) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
